#include <string>

using namespace std;

class Solution {
public:
    string thousandSeparator(int n) {
        if (n == 0) return "0";
        string s = to_string(n), res;
        int len = s.size();
        for (int i = 0; i < len; ++i) {
            if (i && (len - i) % 3 == 0) res += '.';
            res += s[i];
        }
        return res;
    }
};
